// ─── Field editor ─────────────────────────────────────────────────────────────

const FIELD_ORDER: CronFieldName[] = ['minute', 'hour', 'day', 'month', 'weekday'];

function FieldEditor({ fieldName, field, onChange }: {
  fieldName: CronFieldName;
  field: ParsedField;
  onChange: (f: ParsedField) => void;
}) {
  const range = FIELD_RANGES[fieldName];
  const allValues = Array.from({ length: range.max - range.min + 1 }, (_, i) => i + range.min);
  const modes: FieldMode[] = ['every', 'specific', 'range', 'step'];

  const setMode = (mode: FieldMode) => {
    onChange({ ...field, mode, values: mode === 'specific' ? [range.min] : [] });
  };

  const toggleValue = (v: number) => {
    const next = field.values.includes(v)
      ? field.values.filter(x => x !== v)
      : [...field.values, v].sort((a, b) => a - b);
    onChange({ ...field, values: next.length ? next : [v] });
  };

  const label = (v: number) => {
    if (fieldName === 'weekday') return WEEKDAY_NAMES[v];
    if (fieldName === 'month') return MONTH_NAMES[v - 1];
    return String(v);
  };

  const cols = fieldName === 'minute' || fieldName === 'hour' ? 4
    : fieldName === 'weekday' ? 4
    : fieldName === 'month' ? 3 : 4;

  return (
    <FieldCard>
      <FieldHeader>
        <FieldName>{FIELD_LABELS[fieldName]}</FieldName>
        <FieldValue>{fieldToString(field)}</FieldValue>
      </FieldHeader>
      <FieldBody>
        <ModeTabs>
          {modes.map(m => (
            <ModeTab key={m} active={field.mode === m} onClick={() => setMode(m)}>
              {m === 'every' ? '*' : m === 'specific' ? '#' : m === 'range' ? '—' : '/N'}
            </ModeTab>
          ))}
        </ModeTabs>

        {field.mode === 'every' && (
          <DescSub style={{ fontSize: 11 }}>Every {FIELD_LABELS[fieldName].toLowerCase()}</DescSub>
        )}

        {field.mode === 'step' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            <SmallInput
              type="number" min={1} max={range.max}
              value={field.step}
              onChange={e => onChange({ ...field, step: Math.max(1, parseInt(e.target.value) || 1) })}
              placeholder="step"
            />
          </div>
        )}

        {field.mode === 'range' && (
          <RangeRow>
            <SmallInput
              type="number" min={range.min} max={range.max}
              value={field.rangeFrom}
              onChange={e => onChange({ ...field, rangeFrom: parseInt(e.target.value) || range.min })}
              style={{ width: 56 }}
            />
            <span>–</span>
            <SmallInput
              type="number" min={range.min} max={range.max}
              value={field.rangeTo}
              onChange={e => onChange({ ...field, rangeTo: parseInt(e.target.value) || range.max })}
              style={{ width: 56 }}
            />
          </RangeRow>
        )}

        {field.mode === 'specific' && (
          <CheckGrid cols={cols}>
            {allValues.map(v => (
              <CheckItem key={v} active={field.values.includes(v)} onClick={() => toggleValue(v)}>
                {label(v)}
              </CheckItem>
            ))}
          </CheckGrid>
        )}
      </FieldBody>
    </FieldCard>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────

interface AppProps { topBarRight?: React.ReactNode; }

export default function App({ topBarRight }: AppProps) {
  const [expression, setExpression] = useState('*/5 * * * *');
  const [menuOpen, setMenuOpen] = useState(false);
  const [saveOpen, setSaveOpen] = useState(false);
  const menuRef = useRef<HTMLDivElement>(null);

  const handleSave = async (name: string) => {
    setSaveOpen(false);
    await saveDoc('cronbuilder', name, expression);
  };

  useEffect(() => {
    const h = (e: MouseEvent) => { if (menuRef.current && !menuRef.current.contains(e.target as Node)) setMenuOpen(false); };
    document.addEventListener('mousedown', h);
    return () => document.removeEventListener('mousedown', h);
  }, []);

  const parsed = useMemo(() => parseCron(expression), [expression]);

  const updateField = (fieldName: CronFieldName, field: ParsedField) => {
    const next = { ...parsed.fields, [fieldName]: field };
    setExpression(buildExpression(next));
  };

  const handleExpressionInput = (val: string) => {
    setExpression(val);
  };

  const description = useMemo(() => describeExpression(expression), [expression]);
  const nextRuns = useMemo(() => {
    if (!parsed.valid) return [];
    return getNextRuns(expression, new Date(), 8);
  }, [expression, parsed.valid]);

  const appTopBarRight = (
    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
      <DocumentsMenu appId="cronbuilder" onLoad={setExpression} />
      <SaveBtn onClick={() => setSaveOpen(true)}><Save size={14} />Save</SaveBtn>
      <DropdownWrapper ref={menuRef}>
        <DropdownBtn onClick={() => setMenuOpen(o => !o)}>Examples <ChevronDown size={12} /></DropdownBtn>
        {menuOpen && (
          <DropdownMenu>
            {EXAMPLES.map(ex => (
              <DropdownItem key={ex.label} onClick={() => { setExpression(ex.expression); setMenuOpen(false); }}>
                <div>{ex.label}</div>
                <div style={{ fontSize: 11, color: theme.colors.mainTextMuted }}>{ex.expression}</div>
              </DropdownItem>
            ))}
          </DropdownMenu>
        )}
      </DropdownWrapper>
      {topBarRight}
    </div>
  );

  return (
    <Layout title="Cron Builder" sidebar={null} topBarRight={appTopBarRight}>
      {saveOpen && <SaveDialog onSave={handleSave} onCancel={() => setSaveOpen(false)} />}

      <Body>
        <ExpressionBar>
          <ExpressionInput
            value={expression}
            onChange={e => handleExpressionInput(e.target.value)}
            spellCheck={false}
          />
          <DescBadge>{parsed.valid ? description : <span style={{ color: '#f87171' }}>{parsed.error}</span>}</DescBadge>
        </ExpressionBar>

        <FieldsRow>
          {FIELD_ORDER.map(name => (
            <FieldEditor
              key={name}
              fieldName={name}
              field={parsed.fields[name]}
              onChange={f => updateField(name, f)}
            />
          ))}
        </FieldsRow>

        <BottomRow>
          <DescCard>
            <div style={{ fontSize: 11, fontWeight: 700, letterSpacing: '0.07em', textTransform: 'uppercase', color: theme.colors.mainTextMuted }}>Description</div>
            <DescText>{description}</DescText>
            <DescSub>
              <span style={{ fontFamily: theme.typography.fontFamilyMono, color: theme.colors.accent }}>{expression}</span>
            </DescSub>
            <div style={{ marginTop: 'auto', fontSize: 12, color: theme.colors.mainTextMuted, lineHeight: 1.8 }}>
              <div><code style={{ color: theme.colors.accent }}>*</code> — every value</div>
              <div><code style={{ color: theme.colors.accent }}>*/n</code> — every n values</div>
              <div><code style={{ color: theme.colors.accent }}>a-b</code> — range from a to b</div>
              <div><code style={{ color: theme.colors.accent }}>a,b,c</code> — specific values</div>
            </div>
          </DescCard>

          <RunsCard>
            <RunsHeader><Clock size={12} /> Next 8 runs</RunsHeader>
            <RunsList>
              {nextRuns.map((d, i) => (
                <RunItem key={i} index={i}>
                  <RunIndex>#{i + 1}</RunIndex>
                  <RunTime>{d.toLocaleString()}</RunTime>
                </RunItem>
              ))}
              {!parsed.valid && (
                <RunItem index={0}><span style={{ color: '#f87171', fontSize: 11 }}>Fix expression to see next runs</span></RunItem>
              )}
            </RunsList>
          </RunsCard>
        </BottomRow>
      </Body>
    </Layout>
  );
}
